// Form stand-ins. Enough for modules that import the UI layer to load; the
// tests here exercise logic, not form rendering.
class Base {
  constructor() { this.parts = [] }
  title(t) { this.parts.push(["title", t]); return this }
  body(t) { this.parts.push(["body", t]); return this }
  button(t, icon) { this.parts.push(["button", t, icon]); return this }
  async show() { return { canceled: true } }
}
export class ActionFormData extends Base {}
export class ModalFormData extends Base {
  textField(l, p, o) { this.parts.push(["text", l, p, o]); return this }
  toggle(l, o) { this.parts.push(["toggle", l, o]); return this }
  slider(l, min, max, o) { this.parts.push(["slider", l, min, max, o]); return this }
  dropdown(l, opts, o) { this.parts.push(["dropdown", l, opts, o]); return this }
}
export class MessageFormData extends Base {
  button1(t) { this.parts.push(["b1", t]); return this }
  button2(t) { this.parts.push(["b2", t]); return this }
}
